let welcome=["Eat the dots, grow longer, and keep clear of the walls.","Your snake goes wherever you point. Where will it go first?","Every dot you eat adds one segment in that dot's colour.","Steer with your mouse, the arrow keys, or the joystick on a phone.","Pick a mode, press Start, and chase your best score.","Try a 15-second sprint: how many dots can you grab?","Infinite mode has no clock. Play as long as you can stay out of trouble.","The glow around the board takes the colour of your newest tail segment.","Each mode keeps its own best score. Can you beat all four?","Want music? Open the music menu at the top and press Play music.","Ready when you are. Move carefully once your snake gets long."],tips=["Each dot you eat is worth one point and adds one segment to your tail.","Hitting any edge of the board ends the game, so give the walls some room.","The longer your snake gets, the easier it is to run into your own body.","Move in wide loops instead of sharp turns to keep your tail out of the way.","A very fast flick can carry the head across your body without a crash. It is risky, but it works.","In timed modes, head straight for the next dot. There is no prize for style.","On a phone, tilt the joystick a little to creep and push it to the edge to dash.","Let go of the joystick and your snake stops where it is, just like a resting mouse.","Arrow keys and WASD steer too. Hold two keys to move diagonally.","Press Esc, or tap End, to finish a game early.","Your best score for each mode is saved in this browser.","The glow around the board shows the colour of your newest tail segment.","Plan your path to the next dot before your tail gets in the way.","Smooth, steady movement beats sudden jerks once the snake is long.","Switch to the 60-second mode when you want a longer sprint.","Turn on background music and set the music and sound effect volumes separately in the music menu.","Take a break if your hand gets tired. A relaxed grip steers better.","Keep the head near the middle of the board so you always have room to turn."],shownTips=JSON.parse(localStorage.getItem("SuperSnake::shown_tips"))||[];function getRandomTip(){for(let e=tips.length-1;e>0;e--){const o=Math.floor(Math.random()*(e+1));[tips[e],tips[o]]=[tips[o],tips[e]]}shownTips=shownTips.filter(e=>e<tips.length),shownTips.length>=tips.length&&(shownTips=[]);let e=0;for(;shownTips.includes(e);)e=Math.floor(Math.random()*tips.length);return shownTips.push(e),localStorage.setItem("SuperSnake::shown_tips",JSON.stringify(shownTips)),tips[e]}let shownWelcome=JSON.parse(localStorage.getItem("SuperSnake::shown_welcome"))||[];function getRandomWelcome(){for(let e=welcome.length-1;e>0;e--){const o=Math.floor(Math.random()*(e+1));[welcome[e],welcome[o]]=[welcome[o],welcome[e]]}shownWelcome=shownWelcome.filter(e=>e<welcome.length),shownWelcome.length>=welcome.length&&(shownWelcome=[]);let e=0;for(;shownWelcome.includes(e);)e=Math.floor(Math.random()*welcome.length);return shownWelcome.push(e),localStorage.setItem("SuperSnake::shown_welcome",JSON.stringify(shownWelcome)),welcome[e]}